              <CMSProvider>
                <CartProvider>
                  <Toaster />
                  <Router />
                  <WhatsAppWidget />
                </CartProvider>
              </CMSProvider>
            </AuthProvider>
          </TooltipProvider>
        </ThemeProvider>
      </QueryClientProvider>
    </ErrorBoundary>
  );
}

export default App;

