            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {transfers.map((transfer, index) => (
                <TourCard key={transfer.id} tour={transfer} index={index} />
              ))}
            </div>
          )}
        </div>
      </div>
    </Layout>
  );
}

