                    <Button variant="outline" size="sm" onClick={() => handleEditBooking(booking)}>
                      <Pencil className="h-4 w-4 mr-2" /> Modify
                    </Button>
                    <Button size="sm" onClick={() => handleViewBooking(booking)}>
                      <Eye className="h-4 w-4 mr-2" /> View Details
