import type { Express, Request, Response, NextFunction } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { insertBookingSchema, insertTourSchema, insertUserSchema, insertContentBlockSchema, insertSiteSettingSchema, insertPaymentGatewaySchema, insertPaymentSchema, insertWishlistItemSchema, insertNewsletterSubscriberSchema, insertCmsContentSchema } from "@shared/schema";
import bcrypt from "bcryptjs";

// Auth middleware
function requireAuth(req: Request, res: Response, next: NextFunction) {
  if (!req.session.userId) {
    return res.status(401).json({ error: "Authentication required" });
  }
  next();
}

function requireAdmin(req: Request, res: Response, next: NextFunction) {
  if (!req.session.userId) {
    return res.status(401).json({ error: "Authentication required" });
  }
  if (req.session.userRole !== "admin") {
    return res.status(403).json({ error: "Admin access required" });
  }
  next();
}

export async function registerRoutes(
  httpServer: Server,
  app: Express
): Promise<Server> {

  // Auth API
  app.post("/api/auth/login", async (req: Request, res: Response) => {
    try {
      const { email, password } = req.body;

      if (!email || !password) {
        return res.status(400).json({ error: "Email and password are required" });
      }

      const user = await storage.getUserByEmail(email);
      if (!user) {
        return res.status(401).json({ error: "Invalid email or password" });
      }

      // Check password (supporting both hashed and plain text for backward compatibility)
      let isValidPassword = false;
      if (user.password.startsWith('$2')) {
        // Bcrypt hashed password
        isValidPassword = await bcrypt.compare(password, user.password);
      } else {
        // Plain text password (legacy)
        isValidPassword = user.password === password;
      }

      if (!isValidPassword) {
        return res.status(401).json({ error: "Invalid email or password" });
      }

      // Set session
      req.session.userId = user.id;
      req.session.userRole = user.role;

      res.json({
        id: user.id,
        username: user.username,
        email: user.email,
        name: user.name,
        role: user.role,
      });
    } catch (error) {
      console.error("Login error:", error);
      res.status(500).json({ error: "Login failed" });
    }
  });

  app.post("/api/auth/logout", (req: Request, res: Response) => {
    req.session.destroy((err) => {
      if (err) {
        return res.status(500).json({ error: "Logout failed" });
      }
      res.clearCookie("connect.sid");
      res.json({ message: "Logged out successfully" });
    });
  });

  app.get("/api/auth/me", async (req: Request, res: Response) => {
    try {
      if (!req.session.userId) {
        return res.status(401).json({ error: "Not authenticated" });
      }

      const user = await storage.getUser(req.session.userId);
      if (!user) {
        req.session.destroy(() => {});
        return res.status(401).json({ error: "User not found" });
      }

      res.json({
        id: user.id,
        username: user.username,
        email: user.email,
        name: user.name,
        role: user.role,
      });
    } catch (error) {
      res.status(500).json({ error: "Failed to get user" });
    }
  });

  // Tours API
  app.get("/api/tours", async (req, res) => {
    try {
      const tours = await storage.getTours();
      res.json(tours);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch tours" });
    }
  });

  app.get("/api/tours/:id", async (req, res) => {
    try {
      const tour = await storage.getTour(req.params.id);
      if (!tour) {
        return res.status(404).json({ error: "Tour not found" });
      }
      res.json(tour);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch tour" });
    }
  });

  app.post("/api/tours", requireAdmin, async (req, res) => {
    try {
      const validatedData = insertTourSchema.parse(req.body);
      const tour = await storage.createTour(validatedData);
      res.status(201).json(tour);
    } catch (error) {
      res.status(400).json({ error: "Invalid tour data" });
    }
  });

  app.put("/api/tours/:id", requireAdmin, async (req, res) => {
    try {
      const existingTour = await storage.getTour(req.params.id);
      if (!existingTour) {
        return res.status(404).json({ error: "Tour not found" });
      }
      const tour = await storage.updateTour(req.params.id, req.body);
      res.json(tour);
    } catch (error) {
      console.error("Tour update error:", error);
      res.status(400).json({ error: "Failed to update tour" });
    }
  });

  app.delete("/api/tours/:id", requireAdmin, async (req, res) => {
    try {
      const existingTour = await storage.getTour(req.params.id);
      if (!existingTour) {
        return res.status(404).json({ error: "Tour not found" });
      }
      await storage.deleteTour(req.params.id);
      res.json({ message: "Tour deleted successfully" });
    } catch (error) {
      console.error("Tour delete error:", error);
      res.status(500).json({ error: "Failed to delete tour" });
    }
  });

  // Bookings API (admin can see all, users can see their own)
  app.get("/api/bookings", requireAdmin, async (req, res) => {
    try {
      const bookings = await storage.getBookings();
      res.json(bookings);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch bookings" });
    }
  });

  // Export bookings as CSV (admin only) - must be before :id route
  app.get("/api/bookings/export", requireAdmin, async (req, res) => {
    try {
      const bookings = await storage.getBookings();

      // Helper to escape CSV fields properly
      const escapeCSV = (value: string | number | null | undefined): string => {
        const str = String(value ?? '');
        if (str.includes(',') || str.includes('"') || str.includes('\n')) {
          return `"${str.replace(/"/g, '""')}"`;
        }
        return str;
      };

      const csvHeader = "ID,Customer,Tour,Date,Amount,Status,Guests\n";
      const csvRows = bookings.map(b => 
        [b.id, b.customerName, b.tourName, b.date, b.amount, b.status, b.guests]
          .map(escapeCSV)
          .join(',')
      ).join("\n");

      res.setHeader("Content-Type", "text/csv");
      res.setHeader("Content-Disposition", "attachment; filename=bookings.csv");
      res.send(csvHeader + csvRows);
    } catch (error) {
      res.status(500).json({ error: "Failed to export bookings" });
    }
  });

  app.get("/api/bookings/user/:userId", requireAuth, async (req, res) => {
    try {
      // Users can only access their own bookings unless admin
      if (req.session.userRole !== 'admin' && req.session.userId !== req.params.userId) {
        return res.status(403).json({ error: "Access denied" });
      }
      const bookings = await storage.getUserBookings(req.params.userId);
      res.json(bookings);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch user bookings" });
    }
  });

  app.get("/api/bookings/:id", requireAuth, async (req, res) => {
    try {
      const booking = await storage.getBooking(req.params.id);
      if (!booking) {
        return res.status(404).json({ error: "Booking not found" });
      }
      // Users can only see their own bookings unless admin
      if (req.session.userRole !== 'admin' && booking.userId !== req.session.userId) {
        return res.status(403).json({ error: "Access denied" });
      }
      res.json(booking);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch booking" });
    }
  });

  app.post("/api/bookings", requireAuth, async (req, res) => {
    try {
      const validatedData = insertBookingSchema.parse(req.body);
      const booking = await storage.createBooking(validatedData);
      res.status(201).json(booking);
    } catch (error) {
      console.error("Booking creation error:", error);
      res.status(400).json({ error: "Invalid booking data" });
    }
  });

  app.patch("/api/bookings/:id", requireAuth, async (req, res) => {
    try {
      // Check if user has access to this booking
      const existingBooking = await storage.getBooking(req.params.id);
      if (!existingBooking) {
        return res.status(404).json({ error: "Booking not found" });
      }
      if (req.session.userRole !== 'admin' && existingBooking.userId !== req.session.userId) {
        return res.status(403).json({ error: "Access denied" });
      }
      const booking = await storage.updateBooking(req.params.id, req.body);
      res.json(booking);
    } catch (error) {
      res.status(400).json({ error: "Failed to update booking" });
    }
  });

  app.delete("/api/bookings/:id", requireAdmin, async (req, res) => {
    try {
      await storage.deleteBooking(req.params.id);
      res.status(204).send();
    } catch (error) {
      res.status(500).json({ error: "Failed to delete booking" });
    }
  });

  // Analytics API (admin only)
  app.get("/api/analytics/stats", requireAdmin, async (req, res) => {
    try {
      const stats = await storage.getBookingStats();
      res.json(stats);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch stats" });
    }
  });

  app.get("/api/analytics/revenue", requireAdmin, async (req, res) => {
    try {
      const revenue = await storage.getRevenueByMonth();
      res.json(revenue);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch revenue data" });
    }
  });

  // Users API
  app.post("/api/users", async (req, res) => {
    try {
      const validatedData = insertUserSchema.parse(req.body);
      const user = await storage.createUser(validatedData);
      res.status(201).json({ id: user.id, username: user.username, email: user.email, name: user.name });
    } catch (error) {
      res.status(400).json({ error: "Invalid user data" });
    }
  });

  app.get("/api/users/:id", async (req, res) => {
    try {
      const user = await storage.getUser(req.params.id);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }
      res.json({ id: user.id, username: user.username, email: user.email, name: user.name, role: user.role });
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch user" });
    }
  });

  app.get("/api/customers", requireAdmin, async (req, res) => {
    try {
      const customers = await storage.getCustomers();
      res.json(customers);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch customers" });
    }
  });

  // Content Blocks (CMS) API
  app.get("/api/content-blocks", async (req, res) => {
    try {
      const blocks = await storage.getContentBlocks();
      res.json(blocks);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch content blocks" });
    }
  });

  app.get("/api/content-blocks/:slug", async (req, res) => {
    try {
      const block = await storage.getContentBlock(req.params.slug);
      if (!block) {
        return res.status(404).json({ error: "Content block not found" });
      }
      res.json(block);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch content block" });
    }
  });

  app.put("/api/admin/content-blocks/:slug", requireAdmin, async (req, res) => {
    try {
      const block = await storage.updateContentBlock(req.params.slug, req.body);
      res.json(block);
    } catch (error) {
      res.status(400).json({ error: "Failed to update content block" });
    }
  });

  app.post("/api/admin/content-blocks", requireAdmin, async (req, res) => {
    try {
      const validatedData = insertContentBlockSchema.parse(req.body);
      const block = await storage.upsertContentBlock(validatedData);
      res.status(201).json(block);
    } catch (error) {
      res.status(400).json({ error: "Invalid content block data" });
    }
  });

  // Site Settings API
  app.get("/api/settings", async (req, res) => {
    try {
      const settings = await storage.getSiteSettings();
      res.json(settings);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch settings" });
    }
  });

  app.get("/api/settings/:key", async (req, res) => {
    try {
      const setting = await storage.getSiteSetting(req.params.key);
      if (!setting) {
        return res.status(404).json({ error: "Setting not found" });
      }
      res.json(setting);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch setting" });
    }
  });

  app.put("/api/admin/settings/:key", requireAdmin, async (req, res) => {
    try {
      const setting = await storage.upsertSiteSetting({
        key: req.params.key,
        value: req.body.value
      });
      res.json(setting);
    } catch (error) {
      res.status(400).json({ error: "Failed to update setting" });
    }
  });

  // Payment Gateways API
  app.get("/api/payment-gateways/active", async (req, res) => {
    try {
      const gateway = await storage.getActivePaymentGateway();
      if (!gateway) {
        return res.status(404).json({ error: "No active payment gateway" });
      }
      res.json({
        id: gateway.id,
        slug: gateway.slug,
        displayName: gateway.displayName,
        active: gateway.active,
        isDefault: gateway.isDefault
      });
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch active payment gateway" });
    }
  });

  app.get("/api/payment-gateways", async (req, res) => {
    try {
      const gateways = await storage.getPaymentGateways();
      // Don't expose credentials to non-admins
      const safeGateways = gateways.map(g => ({
        id: g.id,
        slug: g.slug,
        displayName: g.displayName,
        description: g.description,
        active: g.active,
        isDefault: g.isDefault,
        supportedCurrencies: g.supportedCurrencies
      }));
      res.json(safeGateways);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch payment gateways" });
    }
  });

  app.get("/api/admin/payment-gateways", requireAdmin, async (req, res) => {
    try {
      const gateways = await storage.getPaymentGateways();
      res.json(gateways);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch payment gateways" });
    }
  });

  app.put("/api/admin/payment-gateways/:id", requireAdmin, async (req, res) => {
    try {
      const gateway = await storage.updatePaymentGateway(req.params.id, req.body);
      res.json(gateway);
    } catch (error) {
      res.status(400).json({ error: "Failed to update payment gateway" });
    }
  });

  app.post("/api/admin/payment-gateways/:id/set-default", requireAdmin, async (req, res) => {
    try {
      await storage.setDefaultPaymentGateway(req.params.id);
      res.json({ message: "Default gateway set successfully" });
    } catch (error) {
      res.status(400).json({ error: "Failed to set default gateway" });
    }
  });

  // Payments API
  app.get("/api/admin/payments", requireAdmin, async (req, res) => {
    try {
      const payments = await storage.getPayments();
      res.json(payments);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch payments" });
    }
  });

  app.get("/api/payments/booking/:bookingId", requireAuth, async (req, res) => {
    try {
      const payments = await storage.getPaymentsByBooking(req.params.bookingId);
      res.json(payments);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch payments" });
    }
  });

  app.post("/api/payments/initiate", requireAuth, async (req, res) => {
    try {
      const { bookingId, gatewaySlug } = req.body;

      // Get the booking
      const booking = await storage.getBooking(bookingId);
      if (!booking) {
        return res.status(404).json({ error: "Booking not found" });
      }

      // Get the gateway
      let gateway;
      if (gatewaySlug) {
        gateway = await storage.getPaymentGatewayBySlug(gatewaySlug);
      } else {
        gateway = await storage.getActivePaymentGateway();
      }

      if (!gateway) {
        return res.status(400).json({ error: "No active payment gateway found" });
      }

      // Parse amount from booking (remove currency symbols)
      const amountStr = booking.amount.replace(/[^0-9.]/g, '');
      const amount = Math.round(parseFloat(amountStr) * 100); // Convert to cents/smallest unit

      // Create payment record
      const payment = await storage.createPayment({
        bookingId,
        gatewayId: gateway.id,
        amount,
        currency: 'VUV',
        status: 'pending'
      });

      // Return payment info (in production, this would redirect to bank payment page)
      res.json({
        paymentId: payment.id,
        gateway: gateway.displayName,
        amount: payment.amount,
        currency: payment.currency,
        status: payment.status,
        // In production, include redirect URL to bank payment page
        redirectUrl: `/payment/process/${payment.id}`
      });
    } catch (error) {
      console.error("Payment initiation error:", error);
      res.status(400).json({ error: "Failed to initiate payment" });
    }
  });

  // Payment callback/webhook (would be called by banks)
  app.post("/api/payments/callback/:paymentId", async (req, res) => {
    try {
      const { paymentId } = req.params;
      const { status, reference, response } = req.body;

      const payment = await storage.getPayment(paymentId);
      if (!payment) {
        return res.status(404).json({ error: "Payment not found" });
      }

      // Update payment status
      await storage.updatePayment(paymentId, {
        status,
        gatewayReference: reference,
        gatewayResponse: response
      });

      // If payment completed, update booking status
      if (status === 'completed') {
        await storage.updateBooking(payment.bookingId, { status: 'confirmed' });
      }

      res.json({ message: "Payment updated successfully" });
    } catch (error) {
      res.status(400).json({ error: "Failed to process payment callback" });
    }
  });

  // ============================================
  // WISHLIST API
  // ============================================

  // Get user's wishlist
  app.get("/api/wishlist", requireAuth, async (req, res) => {
    try {
      const userId = req.session.userId!;
      const items = await storage.getWishlistItems(userId);
      res.json(items);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch wishlist" });
    }
  });

  // Check if tour is in wishlist
  app.get("/api/wishlist/check/:tourId", requireAuth, async (req, res) => {
    try {
      const userId = req.session.userId!;
      const { tourId } = req.params;
      const inWishlist = await storage.isInWishlist(userId, tourId);
      res.json({ inWishlist });
    } catch (error) {
      res.status(500).json({ error: "Failed to check wishlist" });
    }
  });

  // Add to wishlist
  app.post("/api/wishlist", requireAuth, async (req, res) => {
    try {
      const userId = req.session.userId!;
      const { tourId } = req.body;

      if (!tourId) {
        return res.status(400).json({ error: "Tour ID is required" });
      }

      // Check if already in wishlist
      const existing = await storage.getWishlistItem(userId, tourId);
      if (existing) {
        return res.json(existing);
      }

      const item = await storage.addToWishlist({ userId, tourId });
      res.status(201).json(item);
    } catch (error) {
      res.status(400).json({ error: "Failed to add to wishlist" });
    }
  });

  // Remove from wishlist
  app.delete("/api/wishlist/:tourId", requireAuth, async (req, res) => {
    try {
      const userId = req.session.userId!;
      const { tourId } = req.params;
      await storage.removeFromWishlist(userId, tourId);
      res.json({ message: "Removed from wishlist" });
    } catch (error) {
      res.status(400).json({ error: "Failed to remove from wishlist" });
    }
  });

  // ============================================
  // NEWSLETTER API
  // ============================================

  // Get all subscribers (admin only)
  app.get("/api/newsletter/subscribers", requireAdmin, async (req, res) => {
    try {
      const subscribers = await storage.getNewsletterSubscribers();
      res.json(subscribers);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch subscribers" });
    }
  });

  // Subscribe to newsletter (public)
  app.post("/api/newsletter/subscribe", async (req, res) => {
    try {
      const { email, name, locale, source } = req.body;

      if (!email) {
        return res.status(400).json({ error: "Email is required" });
      }

      // Basic email validation
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(email)) {
        return res.status(400).json({ error: "Invalid email format" });
      }

      const subscriber = await storage.subscribeNewsletter({ 
        email, 
        name: name || null, 
        locale: locale || 'en',
        source: source || 'website'
      });

      res.status(201).json({ message: "Successfully subscribed!", subscriber });
    } catch (error) {
      console.error("Newsletter subscription error:", error);
      res.status(400).json({ error: "Failed to subscribe" });
    }
  });

  // Unsubscribe from newsletter (public with email in body)
  app.post("/api/newsletter/unsubscribe", async (req, res) => {
    try {
      const { email } = req.body;

      if (!email) {
        return res.status(400).json({ error: "Email is required" });
      }

      await storage.unsubscribeNewsletter(email);
      res.json({ message: "Successfully unsubscribed" });
    } catch (error) {
      res.status(400).json({ error: "Failed to unsubscribe" });
    }
  });

  // ============================================
  // CMS CONTENT API
  // ============================================

  // Get all CMS content for a block (public)
  app.get("/api/cms-content/:blockSlug", async (req, res) => {
    try {
      const { blockSlug } = req.params;
      const locale = req.query.locale as string || undefined;
      const content = await storage.getCmsContent(blockSlug, locale);
      res.json(content);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch CMS content" });
    }
  });

  // Get all CMS content (admin)
  app.get("/api/cms-content", requireAdmin, async (req, res) => {
    try {
      // Get content for all blocks
      const blocks = await storage.getContentBlocks();
      const allContent: Record<string, any[]> = {};

      for (const block of blocks) {
        allContent[block.slug] = await storage.getCmsContent(block.slug);
      }

      res.json(allContent);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch CMS content" });
    }
  });

  // Create CMS content (admin)
  app.post("/api/cms-content", requireAdmin, async (req, res) => {
    try {
      const validatedData = insertCmsContentSchema.parse(req.body);
      const content = await storage.createCmsContent(validatedData);
      res.status(201).json(content);
    } catch (error) {
      console.error("CMS content creation error:", error);
      res.status(400).json({ error: "Failed to create CMS content" });
    }
  });

  // Update CMS content (admin)
  app.patch("/api/cms-content/:id", requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const existing = await storage.getCmsContentItem(id);
      if (!existing) {
        return res.status(404).json({ error: "Content not found" });
      }

      const content = await storage.updateCmsContent(id, req.body);
      res.json(content);
    } catch (error) {
      res.status(400).json({ error: "Failed to update CMS content" });
    }
  });

  // Delete CMS content (admin)
  app.delete("/api/cms-content/:id", requireAdmin, async (req, res) => {
    try {
      const { id } = req.params;
      const existing = await storage.getCmsContentItem(id);
      if (!existing) {
        return res.status(404).json({ error: "Content not found" });
      }

      await storage.deleteCmsContent(id);
      res.json({ message: "Content deleted successfully" });
    } catch (error) {
      res.status(400).json({ error: "Failed to delete CMS content" });
    }
  });

  return httpServer;
}

