import { createContext, useContext, useEffect, useState, ReactNode } from "react";

type Theme = "light" | "dark";

interface ThemeContextType {
  theme: Theme;
  toggleTheme: () => void;
  setTheme: (theme: Theme) => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setThemeState] = useState<Theme>(() => {
    if (typeof window !== "undefined") {
      const stored = localStorage.getItem("ace-theme") as Theme;
      if (stored) return stored;
      return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
    }
    return "light";
  });

  useEffect(() => {
    const root = document.documentElement;
    if (theme === "dark") {
      root.classList.add("dark");
    } else {
      root.classList.remove("dark");
    }
    localStorage.setItem("ace-theme", theme);
  }, [theme]);

  const toggleTheme = () => {
    setThemeState((prev) => (prev === "light" ? "dark" : "light"));
  };

  const setTheme = (newTheme: Theme) => {
    setThemeState(newTheme);
  };

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme, setTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  const context = useContext(ThemeContext);
  if (context === undefined) {
    throw new Error("useTheme must be used within a ThemeProvider");
  }
  return context;
}

client/src/components/error-boundary.tsx.content:
import { Component, ReactNode } from "react";

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error("Error caught by boundary:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen flex items-center justify-center bg-background">
          <div className="text-center p-8">
            <h1 className="text-2xl font-bold text-foreground mb-4">Something went wrong</h1>
            <p className="text-muted-foreground mb-4">
              {this.state.error?.message || "An unexpected error occurred"}
            </p>
            <button
              onClick={() => {
                this.setState({ hasError: false, error: null });
                window.location.href = "/";
              }}
              className="px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90"
            >
              Go to Home
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

client/src/lib/cms-context.tsx.content:
import { createContext, useContext, ReactNode, useEffect, useState } from "react";
import { useQuery } from "@tanstack/react-query";

interface ContentBlock {
  id: string;
  slug: string;
  label: string;
  description: string | null;
  enabled: boolean;
  config: Record<string, any> | null;
  updatedAt: string;
}

interface SiteSetting {
  id: string;
  key: string;
  value: Record<string, any>;
  updatedAt: string;
}

interface CMSContextType {
  contentBlocks: ContentBlock[];
  siteSettings: SiteSetting[];
  isBlockEnabled: (slug: string) => boolean;
  getBlockConfig: (slug: string) => Record<string, any> | null;
  getSetting: (key: string) => Record<string, any> | null;
  isLoading: boolean;
  refetch: () => void;
}

const CMSContext = createContext<CMSContextType | undefined>(undefined);

async function fetchContentBlocks(): Promise<ContentBlock[]> {
  const response = await fetch("/api/content-blocks");
  if (!response.ok) throw new Error("Failed to fetch content blocks");
  return response.json();
}

async function fetchSiteSettings(): Promise<SiteSetting[]> {
  const response = await fetch("/api/settings");
  if (!response.ok) throw new Error("Failed to fetch site settings");
  return response.json();
}

export function CMSProvider({ children }: { children: ReactNode }) {
  const { 
    data: contentBlocks = [], 
    isLoading: blocksLoading,
    refetch: refetchBlocks
  } = useQuery({
    queryKey: ["content-blocks"],
    queryFn: fetchContentBlocks,
    staleTime: 5 * 60 * 1000,
  });

  const { 
    data: siteSettings = [], 
    isLoading: settingsLoading,
    refetch: refetchSettings
  } = useQuery({
    queryKey: ["site-settings"],
    queryFn: fetchSiteSettings,
    staleTime: 5 * 60 * 1000,
  });

  const isBlockEnabled = (slug: string): boolean => {
    const block = contentBlocks.find(b => b.slug === slug);
    return block?.enabled ?? true;
  };

  const getBlockConfig = (slug: string): Record<string, any> | null => {
    const block = contentBlocks.find(b => b.slug === slug);
    return block?.config ?? null;
  };

  const getSetting = (key: string): Record<string, any> | null => {
    const setting = siteSettings.find(s => s.key === key);
    return setting?.value ?? null;
  };

  const refetch = () => {
    refetchBlocks();
    refetchSettings();
  };

  return (
    <CMSContext.Provider
      value={{
        contentBlocks,
        siteSettings,
        isBlockEnabled,
        getBlockConfig,
        getSetting,
        isLoading: blocksLoading || settingsLoading,
        refetch
      }}
    >
      {children}
    </CMSContext.Provider>
  );
}

export function useCMS() {
  const context = useContext(CMSContext);
  if (context === undefined) {
    throw new Error("useCMS must be used within a CMSProvider");
  }
  return context;
}

export function useContentBlock(slug: string) {
  const { isBlockEnabled, getBlockConfig, isLoading } = useCMS();
  return {
    enabled: isBlockEnabled(slug),
    config: getBlockConfig(slug),
    isLoading
  };
}

