          className="pl-10"
          data-testid="input-newsletter-email"
        />
      </div>
      <Button 
        type="submit" 
        disabled={isLoading}
        data-testid="button-newsletter-subscribe"
      >
        {isLoading ? (
          <Loader2 className="h-4 w-4 animate-spin" />
        ) : (
          <Send className="h-4 w-4" />
        )}
        <span className="sr-only md:not-sr-only md:ml-2">
